window.ANMETA = {"hadith":[{"n":1,"title":"Intentions","part":1},{"n":2,"title":"Islam, Iman, Ihsan","part":1},{"n":3,"title":"Five pillars","part":1},{"n":4,"title":"Creation & destiny","part":1},{"n":5,"title":"No innovation","part":1},{"n":6,"title":"Halal, haram, doubtful","part":1},{"n":7,"title":"Naseehah","part":1},{"n":8,"title":"Sanctity of a Muslim","part":1},{"n":9,"title":"Do what you can","part":1},{"n":10,"title":"Only the good","part":1},{"n":11,"title":"Leave doubt","part":2},{"n":12,"title":"Leave the useless","part":2},{"n":13,"title":"Love for your brother","part":2},{"n":14,"title":"Sanctity of life","part":2},{"n":15,"title":"Good words, neighbour, guest","part":2},{"n":16,"title":"Do not get angry","part":2},{"n":17,"title":"Ihsan in all things","part":2},{"n":18,"title":"Taqwa & character","part":2},{"n":19,"title":"Guard Allah’s limits","part":2},{"n":20,"title":"Hayaa’","part":2},{"n":21,"title":"Istiqamah","part":3},{"n":22,"title":"Obligations to Paradise","part":3},{"n":23,"title":"Purity & good deeds","part":3},{"n":24,"title":"O My servants","part":3},{"n":25,"title":"Charity for all","part":3},{"n":26,"title":"Daily charities","part":3},{"n":27,"title":"Birr and ithm","part":3},{"n":28,"title":"Hold to the Sunnah","part":3},{"n":29,"title":"Doors of good","part":3},{"n":30,"title":"Do not neglect, transgress, violate","part":3},{"n":31,"title":"Zuhd","part":4},{"n":32,"title":"No harm","part":4},{"n":33,"title":"Proof & oath","part":4},{"n":34,"title":"Change evil","part":4},{"n":35,"title":"Brotherhood","part":4},{"n":36,"title":"Help, cover, learn","part":4},{"n":37,"title":"Multiplied rewards","part":4},{"n":38,"title":"Awliya’ of Allah","part":4},{"n":39,"title":"Mistakes forgiven","part":4},{"n":40,"title":"Stranger or traveller","part":4},{"n":41,"title":"Desires follow revelation","part":5},{"n":42,"title":"Forgiveness","part":5},{"n":43,"title":"Inheritance","part":5},{"n":44,"title":"Fosterage","part":5},{"n":45,"title":"Forbidden trade","part":5},{"n":46,"title":"Intoxicants","part":5},{"n":47,"title":"Moderation in eating","part":5},{"n":48,"title":"Signs of hypocrisy","part":5},{"n":49,"title":"Tawakkul","part":5},{"n":50,"title":"Dhikr","part":5}],"parts":[{"k":1,"first":1,"last":10,"label":"Part One","name":"Foundations of the Religion","accent":"#0f5a4f"},{"k":2,"first":11,"last":20,"label":"Part Two","name":"Purity of Heart and Tongue","accent":"#1d4e7a"},{"k":3,"first":21,"last":30,"label":"Part Three","name":"The Paths of Goodness","accent":"#6b2d5c"},{"k":4,"first":31,"last":40,"label":"Part Four","name":"Brotherhood and Justice","accent":"#8a4b12"},{"k":5,"first":41,"last":50,"label":"Part Five","name":"Mercy, Hope and the Additions of Ibn Rajab","accent":"#2f5d34"}],"pass":28,"total":35,"tests":{"1":{"short":[{"q":"What two things does Hadith 1 teach about actions?","a":"An action is valid only with an intention, and its reward depends on what was intended."},{"q":"List the five pillars of Islam.","a":"The two testimonies, prayer, zakah, fasting Ramadan, Hajj."},{"q":"List the six pillars of Īmān.","a":"Belief in Allah, His angels, His books, His messengers, the Last Day, and qadar (good and bad)."},{"q":"Name the three stages of creation in the womb.","a":"Nuṭfah (drop), ʿalaqah (clinging clot), muḍghah (lump of flesh)."},{"q":"What are the two conditions for a deed to be accepted?","a":"Sincerity for Allah (ikhlāṣ) and following the Sunnah."},{"q":"What does a person protect by avoiding doubtful matters?","a":"His religion and his honour."},{"q":"Name the five to whom naṣīḥah is owed.","a":"Allah, His Book, His Messenger, the leaders of the Muslims, and the common Muslims."},{"q":"What does ‘their reckoning is with Allah’ mean in Hadith 8?","a":"We judge by what people show outwardly; their hearts are for Allah to judge."},{"q":"What is the difference between how we treat commands and prohibitions (Hadith 9)?","a":"Prohibitions are left completely; commands are done as much as we are able."},{"q":"Give two things that help a du‘a to be answered, from Hadith 10.","a":"e.g. eating halal, travelling, humility, raising the hands, calling ‘Yā Rabb’."}],"critical":["Two students both help to clean the mosque. One is rewarded and the other is not. Using Hadith 1, explain how this can happen, and how the second student could have earned the reward.","Hadith 2 calls Iḥsān the highest level. Describe what your day would look like if you lived with Iḥsān from morning to night.","Your friend says: “Everything is already written, so there is no point in working hard.” Using Hadith 4, how would you reply kindly and correctly?","Give an example of a ‘doubtful matter’ that young people face today. How do Hadith 6 and the shepherd example help you decide what to do?","Hadith 5 rejects new acts of worship, but Muslims use cars and phones. Explain the difference between worship and worldly matters, with your own examples."]},"2":{"short":[{"q":"What is the difference between a real doubt and waswās?","a":"A real doubt has a reason; waswās is a whisper against something one is already certain of."},{"q":"Give three examples of things that do not concern a person.","a":"e.g. gossip, prying into private lives, useless arguing, endless scrolling."},{"q":"How does Hadith 13 remove envy from the heart?","a":"It makes you want the same good for others that you want for yourself."},{"q":"What are the three cases mentioned in Hadith 14?","a":"The married adulterer, a life for a life, and the one who leaves the religion and separates from the community."},{"q":"What is the right of a guest according to the Sunnah?","a":"Special care for a day and a night; hospitality up to three days."},{"q":"List four remedies for anger.","a":"Seek refuge with Allah, stay silent, change position, make wudu (also: remember the reward of restraint)."},{"q":"Name three rules of kindness when slaughtering an animal.","a":"Sharp knife, not sharpening it in front of the animal, gentleness, quick cut, not slaughtering in front of another animal."},{"q":"What are the three commands of Hadith 18?","a":"Fear Allah wherever you are, follow a bad deed with a good one, treat people with good character."},{"q":"Which steps make repentance sincere?","a":"Stop the sin, regret it, resolve not to return, return any rights to people."},{"q":"What are the two explanations of ‘do as you wish’ in Hadith 20?","a":"A warning (do it and face the consequence), and a permission (if it is not shameful, you may do it)."}],"critical":["Hadith 12 tells us to leave what does not concern us. How can a young Muslim apply this to phones and social media? Give a practical plan.","Is it possible to love for others what you love for yourself while competing with them in an exam or a race? Explain using Hadith 13.","A classmate insults you in front of others. Using Hadith 16 and Hadith 18, describe step by step what you should do, both in the moment and afterwards.","Hadith 19 was taught to a young boy. Why do you think the Prophet ﷺ chose to teach these words to a child? What would change if every child learned them?","Modesty sometimes stops people from asking questions in class. Is that true modesty? Explain using Hadith 20 and the example of the women of the Anṣār."]},"3":{"short":[{"q":"How did ʿUmar explain istiqāmah?","a":"Being steadfast in obedience, and not slipping away like foxes."},{"q":"Why might zakah and Hajj not be mentioned in Hadith 22?","a":"They may not yet have been obligatory, or the man was not able; other hadith complete the picture."},{"q":"Match each deed to its description in Hadith 23: prayer, charity, patience.","a":"Prayer is light; charity is a proof; patience is radiance."},{"q":"Name the four things Hadith 24 says we need to ask Allah for.","a":"Guidance, food, clothing and forgiveness."},{"q":"Why were the Companions surprised by the last charity in Hadith 25, and how was it explained?","a":"Intimacy with one’s spouse; doing it in the haram is a sin, so doing it in the halal earns reward."},{"q":"Give four charities from Hadith 26.","a":"Judging fairly, helping someone with his mount or luggage, a good word, steps to the prayer, removing harm from the road."},{"q":"What should you do in an unclear matter when your heart feels uneasy (Hadith 27)?","a":"Check the texts, ask a scholar, and leave what disturbs the heart."},{"q":"List the four commands of the Prophet ﷺ in Hadith 28.","a":"Taqwā; listening and obeying; holding to the Sunnah and the rightly guided caliphs; avoiding newly invented matters."},{"q":"Name the three ‘doors of good’ in Hadith 29.","a":"Fasting is a shield; charity puts out sin; prayer in the depths of the night."},{"q":"What are the four kinds of matters in Hadith 30?","a":"Obligations, limits, prohibitions, and things left unmentioned out of mercy."}],"critical":["Hadith 22 shows that doing only the obligations leads to Paradise. Why, then, do Muslims still do voluntary deeds? Give at least three reasons.","‘Every person goes out in the morning selling himself.’ Describe a normal school or work day and show where a person ‘frees’ or ‘ruins’ his soul.","Hadith 24 says obeying Allah adds nothing to His kingdom. If Allah does not need our worship, why do we worship Him? Explain using the hadith.","The tongue can destroy a person’s good deeds (Hadith 29). Choose three sins of the tongue that are common today and suggest a practical cure for each.","Hadith 30 says Allah left some things unmentioned as a mercy. How does this protect Muslims from two extremes: making the halal haram, and inventing new worship?"]},"4":{"short":[{"q":"Does zuhd mean being poor? Explain.","a":"No. It means the world is in your hand, not your heart; you leave what does not benefit the Hereafter."},{"q":"What is the difference between ḍarar and ḍirār?","a":"Ḍarar is harming someone at all; ḍirār is harming in return, beyond what is just."},{"q":"Give two examples of rulings built on Hadith 32.","a":"e.g. a neighbour may not build what seriously harms his neighbour; a will may not be made to harm the heirs."},{"q":"What counts as ‘proof’ (bayyinah) in Hadith 33?","a":"Witnesses or clear evidence."},{"q":"Name three conditions before changing an evil.","a":"Knowledge that it is an evil, ability/authority, gentleness, and that it does not lead to a greater evil."},{"q":"List the five ‘do not’s at the start of Hadith 35.","a":"Do not envy, inflate prices, hate, turn your backs, or undercut each other’s sales."},{"q":"What does ‘covering a Muslim’ mean, and what does it not mean?","a":"Not exposing a private mistake; it does not mean hiding harm or crimes against others."},{"q":"When is leaving a bad deed written as a good deed?","a":"When it is left for the sake of Allah."},{"q":"What happens when Allah loves a servant (Hadith 38)?","a":"He guides his hearing, sight, hands and feet, answers his du‘a and grants him refuge."},{"q":"Explain Ibn ʿUmar’s advice at the end of Hadith 40.","a":"Do not delay good deeds from evening to morning; use health before sickness and life before death."}],"critical":["Zuhd (Hadith 31) and working hard to earn halal money can seem to clash. Explain how a Muslim can be both successful at work and a zāhid.","Using Hadith 33, explain why we should not believe or share rumours on social media. What would happen to a community that ignored this rule?","You see a friend doing something wrong. Using Hadith 34, decide which level applies to you and write exactly what you would say or do.","Hadith 37 shows how generous Allah is in recording deeds. How should this change the way you plan your week? Give examples of intentions you could make.","If you truly lived ‘as a stranger or a wayfarer’ (Hadith 40), what would you do differently with your time, money and belongings?"]},"5":{"short":[{"q":"What does hawā mean, and why is following it against the Shariah dangerous?","a":"What the soul desires; following it against revelation is the root of sins and innovations."},{"q":"Name the three means of forgiveness in Hadith 42.","a":"Du‘a with hope, seeking forgiveness (istighfār), and meeting Allah with tawḥīd."},{"q":"Put these in order: bequest, funeral costs, inheritance shares, debts.","a":"Funeral costs, debts, bequest, inheritance shares."},{"q":"Name four relatives who become maḥram through fosterage.","a":"The foster mother, foster father (her husband), foster siblings, foster aunts, foster grandparents."},{"q":"What general rule did scholars take from Hadith 45?","a":"When Allah forbids something to be used, He forbids its price."},{"q":"Why is Hadith 46 an example of jawāmiʿ al-kalim?","a":"One short sentence gives a rule that covers every intoxicant in every age."},{"q":"List four manners of eating from the Sunnah.","a":"Bismillah, right hand, eat from what is in front of you, do not criticise food, praise Allah after."},{"q":"What are the two kinds of hypocrisy?","a":"Major (in belief) and minor (in actions)."},{"q":"Explain the difference between tawakkul and laziness.","a":"Tawakkul is relying on Allah while taking the means; laziness abandons the means."},{"q":"Why is dhikr called an easy deed?","a":"It needs no money, place or special time and can be done in any position."}],"critical":["Hadith 42 gives great hope. How would you use it to help a friend who feels his sins are too many — without making him careless about sin?","A Muslim company calls interest a ‘service fee’. Using Hadith 45 and the story of the melted fat, explain why the name does not change the ruling.","Plan one week of meals for yourself or your family that follows Hadith 47. What changes would you make, and what benefits do you expect?","Which of the four signs of hypocrisy (Hadith 48) is most common in school or work today? Suggest a practical way to fight it.","You have finished the fifty hadith. Choose the three that changed you the most and explain why, ending with how Hadith 50 can keep you steadfast."]}}};
